 "content": "def transform(grid):
    counts = {3: 0, 2: 0}
    for row in grid:
        for color in (3, 2):
            in_run = False
            for value in row:
                if value == color and not in_run:
                    counts[color] += 1
                in_run = value == color
    cells = [3] * counts[3] + [2] * counts[2]
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]
